        if (!adapter) {
          toast.error('Cannot update application because no data adapter is configured.');
          return;
        }
        const client = adapter.getClient();
        if (!client) {
          toast.error('Cannot update application because the data adapter client is unavailable.');
          return;
        }
        await client.meta.saveItem('app', draft.name, appSchema);
